  8	/// is TU3's coach panel and Help ▸ Tutorials.
  9	///
 10	/// Every answer but a refusal is the runner's state, `{ok, project,
 11	/// running}` and, while one runs, `TutorialRunner.state()`. A refusal — no
 12	/// editor window, an unknown or refused id, unmet needs, a move the step does
 13	/// not offer — is the runner's own sentence.
 14	///
 15	/// `tutorial_start`, `tutorial_state` and `tutorial_exit` run on MAIN.
 16	/// `tutorial_start`'s answer is made in its own main block, so it shows step
 17	/// 1; the start's evaluation runs on a later main turn, before any later
 18	/// tool's main block (the main queue is first in, first out).
 19	/// `tutorial_step` runs on the SERVER thread (`devOffMainTools`): `show_me`
 20	/// presses Show Me on main, then waits WITHOUT the lane's lock
 21	/// (`AgentLane.releasingLock`, as `assistant_send` does), reading the
 22	/// runner on main every 50 ms for up to 60 s, because Show Me's own calls go
 23	/// through the lane's `submit` and need the lock.
 24	extension AgentServer {
 25	
 26	    func tutorialStart(_ a: [String: Any]) throws -> String {
 27	        guard let id = try stringArg(a, "id") else {
 28	            throw ToolError(message: "Missing required argument: id")
 29	        }
 30	        let (editor, project) = try tutorialEditor(a)
 31	        let library: TutorialLibrary
 32	        do {
 33	            library = try TutorialLibrary.bundled()
 34	        } catch {
 35	            throw ToolError(message: error.localizedDescription)
 36	        }
 37	        if let reason = library.refused[id] {
 38	            throw ToolError(message: "The tutorial \(id) does not read: \(reason).")
 39	        }
 40	        guard let tutorial = library.tutorial(id: id) else {
 41	            throw ToolError(
 42	                message: "No tutorial is called \(id); the tutorials are "
 43	                    + library.ids.joined(separator: ", ") + ".")
 44	        }
 45	        do {
 46	            try TutorialRunner.start(tutorial, in: editor)
 47	        } catch let refusal as TutorialRefusal {
 48	            throw ToolError(message: refusal.sentence)
 49	        }
 50	        return try jsonResult(Self.tutorialAnswer(editor, project))
 51	    }
 52	
 53	    func tutorialState(_ a: [String: Any]) throws -> String {
 54	        let (editor, project) = try tutorialEditor(a)
 55	        return try jsonResult(Self.tutorialAnswer(editor, project))
 56	    }
 57	
 58	    func tutorialExit(_ a: [String: Any]) throws -> String {
 59	        let (editor, project) = try tutorialEditor(a)
 60	        guard let runner = editor.tutorialRunner else {
 61	            throw ToolError(message: Self.noTutorial)
 62	        }
 63	        runner.exit()
 64	        return try jsonResult(Self.tutorialAnswer(editor, project))
 65	    }
 66	
 67	    func tutorialStep(_ a: [String: Any]) throws -> String {
 68	        guard let action = try stringArg(a, "action") else {
 69	            throw ToolError(message: "Missing required argument: action")
 70	        }
 71	        guard Self.tutorialActions.contains(action) else {
 72	            throw ToolError(
 73	                message: "action must be show_me, next, back or skip (got \"\(action)\").")
 74	        }
 75	        // This thread holds the editor and the runner only weakly, so it never
 76	        // keeps either alive past an exit or a start while the lock is out.
 77	        weak var watchedEditor: EditorViewController?
 78	        weak var watchedRunner: TutorialRunner?
 79	        let project = try onMain { () throws -> Any in
 80	            let (editor, project) = try self.tutorialEditor(a)
 81	            guard let runner = editor.tutorialRunner else {
 82	                throw ToolError(message: Self.noTutorial)
 83	            }
 84	            do {
 85	                switch action {
 86	                case "show_me": try runner.showMe()
 87	                case "next": try runner.next()
 88	                case "back": try runner.back()
 89	                default: try runner.skip()
 90	                }
 91	            } catch let refusal as TutorialRefusal {
 92	                throw ToolError(message: refusal.sentence)
 93	            }
 94	            watchedEditor = editor
 95	            watchedRunner = runner
 96	            return project
 97	        }
 98	        if action == "show_me" {
 99	            let started = Date()
100	            AgentLane.shared.releasingLock {
101	                while Date().timeIntervalSince(started) < Self.showMeTimeout {
102	                    let running = onMain { () -> Bool in
103	                        guard let editor = watchedEditor, let runner = watchedRunner else {
104	                            return false
105	                        }
106	                        return editor.tutorialRunner === runner && runner.showMeRunning
107	                    }
108	                    guard running else { break }
109	                    Thread.sleep(forTimeInterval: 0.05)
110	                }
111	            }
112	        }
113	        return try jsonResult(
114	            onMain { () throws -> [String: Any] in
115	                let (editor, _) = try self.tutorialEditor(a)
116	                return Self.tutorialAnswer(editor, project)
117	            })
118	    }
119	
120	    private static let tutorialActions: Set<String> = ["show_me", "next", "back", "skip"]
121	    private static let showMeTimeout = 60.0
122	    private static let noTutorial =
123	        "No tutorial is running in this window: tutorial_start starts one."
124	
125	    /// The project's editor and its path for the answer, refused as
126	    /// `select_inspector_tab` refuses a windowless project. Main thread.
127	    private func tutorialEditor(_ a: [String: Any]) throws -> (EditorViewController, Any) {
128	        let document = try target(a)
129	        guard let editor = editor(document), editor.isViewLoaded else {
130	            let name = Self.path(of: document) ?? document.displayName ?? "Untitled"
131	            throw ToolError(
132	                message: "The project \(name) has no window: a tutorial runs only in its editor "
133	                    + "window.")
134	        }
135	        return (editor, UISnapshot.orNull(Self.path(of: document)))
136	    }
137	
138	    /// The state every tool answers. Main thread.
139	    private static func tutorialAnswer(_ editor: EditorViewController, _ project: Any)
140	        -> [String: Any] {
141	        var answer: [String: Any] = ["ok": true, "project": project, "running": false]
142	        if let runner = editor.tutorialRunner {
143	            answer.merge(runner.state()) { _, theirs in theirs }
144	        }
145	        return answer
146	    }
147	
148	    // MARK: - Catalog
149	
150	    func tutorialStartTool() -> [String: Any] {
151	        tool(
152	            "tutorial_start",
153	            "DEV TOOL (absent from Distribution builds). Start a guide tutorial by id in a "
154	                + "project's editor window, replacing any tutorial running there: its needs are "
155	                + "checked first and, when no clip meets them, the call is refused with the "
156	                + "sentence naming what is missing. Answers the runner's state at step 1: ok, "
157	                + "project, running and, while running, id, title, step (1-based), steps, text, "
158	                + "optional, wait, show_me, offers (of back, show_me, skip, next, exit), "
159	                + "spotlight, reveal {tab, sub_tab, section} or null, reveal_refused, finished, "
160	                + "show_me_running, last_show_me {step, ok, error, results, paths} or null, "
161	                + "selection_at_start, created and completed [{step, by}]. A wait already met "
162	                + "advances on a later main turn. Refused: an unknown id (the refusal lists the "
163	                + "tutorials), a tutorial the model does not read (with its reason) and a project "
164	                + "with no window.",
165	            [
166	                "id": [
167	                    "type": "string",
168	                    "description": "The tutorial's id, as its guide page names it "
169	                        + "(audio.volume, editing.split, …).",
170	                ]
171	            ],
172	            required: ["id"])
173	    }
174	
175	    func tutorialStateTool() -> [String: Any] {
176	        tool(
177	            "tutorial_state",
178	            "DEV TOOL (absent from Distribution builds). Answer the state of the tutorial "
179	                + "running in a project's editor window, changing nothing: running false when "
180	                + "none runs, else the fields tutorial_start answers.",
181	            [:])
182	    }
183	
184	    func tutorialStepTool() -> [String: Any] {
185	        tool(
186	            "tutorial_step",
187	            "DEV TOOL (absent from Distribution builds). Press one of the running tutorial's "
188	                + "buttons: show_me runs the step's Show Me — its tool calls through the "
189	                + "assistant's lane with ordinary undo, its menu items through the menu bar's "
190	                + "own validated item — and answers once it has finished (up to 60 s), its "
191	                + "outcome in last_show_me; next goes on from a step with no wait; back re-begins "
192	                + "the step before (or the last, once finished) and does not evaluate it; skip "
193	                + "passes an optional step. Answers the state. Refused in the runner's own "
194	                + "sentence: a move the step does not offer, and no tutorial running.",
195	            [
196	                "action": [
197	                    "type": "string", "enum": ["show_me", "next", "back", "skip"],
198	                    "description": "The button: show_me, next, back or skip.",
199	                ]
200	            ],
201	            required: ["action"])
202	    }
203	
204	    func tutorialExitTool() -> [String: Any] {
205	        tool(
206	            "tutorial_exit",
207	            "DEV TOOL (absent from Distribution builds). End the tutorial running in a "
208	                + "project's editor window, undoing nothing. Answers the state (running false). "
209	                + "Refused when no tutorial runs there.",
210	            [:])
211	    }
212	}
213	#endif

content.content:
  1	import AppKit
  2	
  3	/// A move the runner does not offer, in one sentence (spec §11 TU-8 (2), (6)).
  4	struct TutorialRefusal: Error {
  5	    let sentence: String
  6	}
  7	
  8	/// How a step was left: its wait met, Next, or Skip.
  9	enum TutorialAdvance: String {
 10	    case wait, next, skip
 11	}
 12	
 13	/// How a step was entered. A forward entry — start, Next, Skip, a met wait —
 14	/// is a trigger; a Back entry is not (spec §11 TU-8 (3)).
 15	enum TutorialEntry {
 16	    case forward, back
 17	}
 18	
 19	/// What the last Show Me did (spec §11 TU-9).
 20	struct TutorialShowMeOutcome {
 21	    let step: Int
 22	    let ok: Bool
 23	    let error: String?
 24	    /// Each call's result text, in order.
 25	    let results: [String]
 26	    /// The files an `export` call was sent to write.
 27	    let paths: [String]
 28	}
 29	
 30	/// One tutorial running in one editor window, with no chrome (spec §11
 31	/// TU-8): its needs checked at the start, each step's baseline and reveal as
 32	/// it begins, its wait read after events, and Back, Skip, Next, Exit and Show
 33	/// Me (`TutorialShowMe.swift`, TU-9). The panel that shows it is TU3's; the
 34	/// dev tools (`AgentServer+Tutorials.swift`) drive it until then.
 35	///
 36	/// **Event-driven.** A committed document or view-state change
 37	/// (`documentDidChange`, from the editor's `projectDidChange`), a playhead
 38	/// move (`trigger`, from `inspectorPlayheadMoved`), a rate change, the
 39	/// window's sheet beginning or ending, an export started and a forward step
 40	/// entry each call `trigger()`, which schedules ONE coalesced evaluation on
 41	/// the next main turn — a documented `DispatchQueue.main.async` seam — so the
 42	/// event that met a wait has finished first. Nothing polls. While a Show Me
 43	/// runs every evaluation is held, and one runs after its last entry.
 44	///
 45	/// Owned by `EditorViewController.tutorialRunner`; Exit sets that to nil and
 46	/// undoes nothing, and closing the window ends it. Main only.
 47	final class TutorialRunner {
 48	    let tutorial: Tutorial
 49	    weak var editor: EditorViewController?
 50	    weak var document: ProjectDocument?
 51	
 52	    /// The current step's index, 0-based; the last step's once finished.
 53	    private(set) var index = 0
 54	    private(set) var finished = false
 55	    private var baseline: TutorialBaseline
 56	    /// `$created` now: the ids added by the latest step, or Show Me call,
 57	    /// that added any.
 58	    var created: [UInt32] = []
 59	    /// `created` as each step began, so Back restores it.
 60	    private var createdAtBegin: [Int: [UInt32]] = [:]
 61	    private var latches = TutorialLatches()
 62	    private var revealRefused: String?
 63	    private var completed: [(step: Int, by: TutorialAdvance)] = []
 64	    private var evaluationPending = false
 65	    private var observers: [NSObjectProtocol] = []
 66	    /// The clips' JSON the waits read; the runner's own, so letting the
 67	    /// runner go on any thread touches nothing another runner or main reads.
 68	    private let clipCache: TutorialClipCache
 69	
 70	    // Show Me's state (`TutorialShowMe.swift`).
 71	    /// True from the press until the last entry's answer is back.
 72	    var showMeRunning = false
 73	    /// A trigger arrived while a Show Me ran.
 74	    var heldEvaluation = false
 75	    /// The Show Me in flight; its generation drops a stale completion.
 76	    var showMeRun: TutorialShowMeRun?
 77	    var showMeGeneration = 0
 78	    var lastShowMe: TutorialShowMeOutcome?
 79	
 80	    private init(tutorial: Tutorial, editor: EditorViewController, document: ProjectDocument) {
 81	        self.tutorial = tutorial
 82	        self.editor = editor
 83	        self.document = document
 84	        let cache = TutorialClipCache()
 85	        clipCache = cache
 86	        baseline = TutorialBaseline(document: document, cache: cache)
 87	    }
 88	
 89	    /// Safe on any thread: `NotificationCenter` is thread-safe, and the clip
 90	    /// cache is the runner's own.
 91	    deinit {
 92	        for observer in observers { NotificationCenter.default.removeObserver(observer) }
 93	    }
 94	
 95	    // MARK: - Start and exit
 96	
 97	    /// Starts `tutorial` in `editor`'s window, replacing any running there;
 98	    /// refused, starting nothing, when its needs are unmet.
 99	    @discardableResult
100	    static func start(_ tutorial: Tutorial, in editor: EditorViewController) throws
101	        -> TutorialRunner {
102	        guard let document = editor.document else {
103	            throw TutorialRefusal(sentence: "This window has no project.")
104	        }
105	        if let sentence = TutorialWait.needsSentence(
106	            tutorial.needs, in: document.editedProject.snapshot)
107	        {
108	            throw TutorialRefusal(sentence: sentence)
109	        }
110	        let runner = TutorialRunner(tutorial: tutorial, editor: editor, document: document)
111	        editor.tutorialRunner = runner
112	        runner.observeSheets(editor.view.window)
113	        runner.begin(0, .forward)
114	        return runner
115	    }
116	
117	    /// Ends the tutorial; the project and its undo history stay as they are.
118	    func exit() {
119	        guard let editor, editor.tutorialRunner === self else { return }
120	        editor.tutorialRunner = nil
121	    }
122	
123	    private func observeSheets(_ window: NSWindow?) {
124	        guard let window else { return }
125	        for name in [NSWindow.willBeginSheetNotification, NSWindow.didEndSheetNotification] {
126	            observers.append(
127	                NotificationCenter.default.addObserver(forName: name, object: window, queue: nil) {
128	                    [weak self] _ in self?.trigger()
129	                })
130	        }
131	    }
132	
133	    // MARK: - Triggers
134	
135	    /// Schedules one evaluation on the next main turn, or holds it while a
136	    /// Show Me runs.
137	    func trigger() {
138	        if showMeRunning {
139	            heldEvaluation = true
140	            return
141	        }
142	        guard !evaluationPending else { return }
143	        evaluationPending = true
144	        DispatchQueue.main.async { [weak self] in self?.evaluate() }
145	    }
146	
147	    /// A committed change or a view-state change; a live tick is ignored.
148	    func documentDidChange(isLive: Bool) {
149	        guard !isLive else { return }
150	        trigger()
151	    }
152	
153	    func playbackRateChanged(_ rate: Float) {
154	        if rate != 0 { latches.playing = true }
155	        trigger()
156	    }
157	
158	    /// The sheet's Export… or Add to Queue, or the `export` tool, started one.
159	    func noteExportStarted() {
160	        latches.exportStarted = true
161	        trigger()
162	    }
163	
164	    private func evaluate() {
165	        evaluationPending = false
166	        if showMeRunning {
167	            heldEvaluation = true
168	            return
169	        }
170	        guard !finished, let editor, editor.tutorialRunner === self, let document else { return }
171	        let step = currentStep
172	        guard !step.wait.isEmpty,
173	              TutorialWait.met(
174	                step.wait, baseline: baseline, created: created, latches: latches,
175	                document: document, window: editor.view.window, cache: clipCache)
176	        else { return }
177	        advance(by: .wait)
178	    }
179	
180	    // MARK: - Navigation
181	
182	    var currentStep: TutorialStep { tutorial.steps[index] }
183	
184	    /// `$selection`: the step's start selection, in time order.
185	    var selectionAtStart: [UInt32] { baseline.selection }
186	
187	    /// Begins step `next`: its baseline, then its reveal; a forward entry is
188	    /// a trigger.
189	    private func begin(_ next: Int, _ entry: TutorialEntry) {
190	        index = next
191	        finished = false
192	        switch entry {
193	        case .forward: createdAtBegin[next] = created
194	        case .back: created = createdAtBegin[next] ?? created
195	        }
196	        if let document { baseline = TutorialBaseline(document: document, cache: clipCache) }
197	        latches = TutorialLatches()
198	        revealRefused = nil
199	        if let reveal = currentStep.reveal {
200	            if let inspector = editor?.inspector, inspector.isViewLoaded {
201	                revealRefused = inspector.reveal(reveal)
202	            } else {
203	                revealRefused = "The window has no inspector."
204	            }
205	        }
206	        if entry == .forward { trigger() }
207	    }
208	
209	    private func advance(by how: TutorialAdvance) {
210	        completed.append((index + 1, how))
211	        if let document {
212	            let snapshot = document.editedProject.snapshot
213	            let added = snapshot.clips.map(\.id).filter { !baseline.clipIDs.contains($0) }
214	            if !added.isEmpty { created = TutorialVariables.timeOrdered(added, in: snapshot) }
215	        }
216	        if index + 1 < tutorial.steps.count {
217	            begin(index + 1, .forward)
218	        } else {
219	            finished = true
220	        }
221	    }
222	
223	    private func refuseWhileShowMe() throws {
224	        if showMeRunning { throw TutorialRefusal(sentence: "Show Me is still running.") }
225	    }
226	
227	    func next() throws {
228	        try refuseWhileShowMe()
229	        if finished { throw TutorialRefusal(sentence: "The tutorial is finished.") }
230	        guard currentStep.wait.isEmpty else {
231	            throw TutorialRefusal(
232	                sentence: "This step goes on by itself once it is done; Next is only on a step "
233	                    + "with nothing to wait for.")
234	        }
235	        advance(by: .next)
236	    }
237	
238	    func skip() throws {
239	        try refuseWhileShowMe()
240	        if finished { throw TutorialRefusal(sentence: "The tutorial is finished.") }
241	        guard currentStep.optional else {
242	            throw TutorialRefusal(sentence: "Only an optional step can be skipped.")
243	        }
244	        advance(by: .skip)
245	    }
246	
247	    func back() throws {
248	        try refuseWhileShowMe()
249	        let target: Int
250	        if finished {
251	            target = index
252	        } else {
253	            guard index > 0 else { throw TutorialRefusal(sentence: "This is the first step.") }
254	            target = index - 1
255	        }
256	        completed.removeAll { $0.step >= target + 1 }
257	        begin(target, .back)
258	    }
259	
260	    // MARK: - The state
261	
262	    /// What the panel offers now, in its order.
263	    var offers: [String] {
264	        var out: [String] = []
265	        if finished || index > 0 { out.append("back") }
266	        if !finished {
267	            let step = currentStep
268	            if !step.showMe.isEmpty { out.append("show_me") }
269	            if step.optional { out.append("skip") }
270	            if step.wait.isEmpty { out.append("next") }
271	        }
272	        out.append("exit")
273	        return out
274	    }
275	
276	    /// The dev tools' answer: where the tutorial is and what it holds.
277	    func state() -> [String: Any] {
278	        let step = currentStep
279	        var reveal: Any = NSNull()
280	        if let shown = step.reveal {
281	            reveal = [
282	                "tab": shown.tab.title.lowercased(),
283	                "sub_tab": shown.subTab.map { $0.rawValue as Any } ?? NSNull(),
284	                "section": shown.section.map { $0 as Any } ?? NSNull(),
285	            ] as [String: Any]
286	        }
287	        var last: Any = NSNull()
288	        if let outcome = lastShowMe {
289	            last = [
290	                "step": outcome.step, "ok": outcome.ok,
291	                "error": outcome.error.map { $0 as Any } ?? NSNull(),
292	                "results": outcome.results, "paths": outcome.paths,
293	            ] as [String: Any]
294	        }
295	        return [
296	            "running": true,
297	            "id": tutorial.id,
298	            "title": tutorial.title,
299	            "step": index + 1,
300	            "steps": tutorial.steps.count,
301	            "text": step.text,
302	            "optional": step.optional,
303	            "wait": !step.wait.isEmpty,
304	            "show_me": !step.showMe.isEmpty,
305	            "offers": offers,
306	            "spotlight": step.spotlight.map { $0 as Any } ?? NSNull(),
307	            "reveal": reveal,
308	            "reveal_refused": revealRefused.map { $0 as Any } ?? NSNull(),
309	            "finished": finished,
310	            "show_me_running": showMeRunning,
311	            "last_show_me": last,
312	            "selection_at_start": baseline.selection.map { Int($0) },
313	            "created": created.map { Int($0) },
314	            "completed": completed.map { ["step": $0.step, "by": $0.by.rawValue] as [String: Any] },
315	        ]
316	    }
317	}

  1	import AppKit
  2	
  3	/// A Show Me in flight: its entries, where it is, and what it has answered.
  4	struct TutorialShowMeRun {
  5	    let entries: [TutorialShowMe]
  6	    let step: Int
  7	    let generation: Int
  8	    var results: [String] = []
  9	    var paths: [String] = []
 10	}
 11	
 12	/// Show Me (spec §11 TU-3, TU-9): the step done the way the app already does
 13	/// it, its entries in order, never blocking main.
 14	///
 15	/// **The tool form** resolves TU-2 (9)'s variables, then goes through
 16	/// `AgentLane.shared.submit` pinned to the runner's document — the
 17	/// assistant's path: the argument gate, the lane's lock, ordinary undo — with
 18	/// ask-first answered yes, since the press is the ask. An `export` call's
 19	/// `path` is made free first (`RecordingFiles.uniqueURL`, the Finder's
 20	/// `<stem> (2).<ext>` rule), so a Show Me never overwrites a file, and the
 21	/// outcome names the file. Its completion hops back to main — a documented
 22	/// `DispatchQueue.main.async` seam — and is dropped when the runner has been
 23	/// replaced or exited. **The menu form** looks the path up in the built menu
 24	/// bar for the editor's window (`UIMenu.lookup`, compiled in every build) and
 25	/// runs the item through `UIMenu.perform`, refused when absent, when nothing
 26	/// answers it or its validator greys it, and when nothing handled it.
 27	///
 28	/// An entry that errors stops the list with its own text; the step stays,
 29	/// and the earlier entries' edits stay. Evaluations are held while it runs
 30	/// (`TutorialRunner.trigger`) and one runs after the last entry.
 31	extension TutorialRunner {
 32	    func showMe() throws {
 33	        if finished { throw TutorialRefusal(sentence: "The tutorial is finished.") }
 34	        if showMeRunning { throw TutorialRefusal(sentence: "Show Me is still running.") }
 35	        let entries = currentStep.showMe
 36	        guard !entries.isEmpty else { throw TutorialRefusal(sentence: "This step has no Show Me.") }
 37	        guard document != nil else { throw TutorialRefusal(sentence: "This window has no project.") }
 38	        showMeGeneration += 1
 39	        showMeRunning = true
 40	        showMeRun = TutorialShowMeRun(entries: entries, step: index + 1, generation: showMeGeneration)
 41	        runShowMeEntry(0)
 42	    }
 43	
 44	    private func runShowMeEntry(_ at: Int) {
 45	        guard let run = showMeRun else { return }
 46	        guard at < run.entries.count else {
 47	            finishShowMe(error: nil)
 48	            return
 49	        }
 50	        guard let document else {
 51	            finishShowMe(error: "The tutorial's project is no longer open.")
 52	            return
 53	        }
 54	        let before = Set(document.editedProject.snapshot.clips.map(\.id))
 55	        switch run.entries[at] {
 56	        case .menu(let path):
 57	            if let refusal = performMenu(path) {
 58	                finishShowMe(error: refusal)
 59	                return
 60	            }
 61	            showMeRun?.results.append(path.joined(separator: " ▸ "))
 62	            noteCreated(since: before)
 63	            runShowMeEntry(at + 1)
 64	        case .tool(let name, let args):
 65	            let json: String
 66	            do {
 67	                var resolved = try TutorialVariables.resolve(
 68	                    args, selection: selectionAtStart, created: created, snapshot: document.editedProject.snapshot,
 69	                    playhead: document.playhead) as? [String: Any] ?? [:]
 70	                if name == "export", let path = resolved["path"] as? String {
 71	                    let free = Self.freeURL(for: path).path
 72	                    resolved["path"] = free
 73	                    showMeRun?.paths.append(free)
 74	                }
 75	                let data = try JSONSerialization.data(withJSONObject: resolved)
 76	                json = String(decoding: data, as: UTF8.self)
 77	            } catch let refusal as TutorialRefusal {
 78	                finishShowMe(error: refusal.sentence)
 79	                return
 80	            } catch {
 81	                finishShowMe(error: error.localizedDescription)
 82	                return
 83	            }
 84	            let generation = run.generation
 85	            AgentLane.shared.submit(
 86	                tool: name, argumentsJSON: json, document: document,
 87	                askFirst: { _, answer in answer(true) },
 88	                completion: { [weak self] result in
 89	                    DispatchQueue.main.async {
 90	                        guard let self, self.showMeGeneration == generation,
 91	                              self.editor?.tutorialRunner === self
 92	                        else { return }
 93	                        self.toolAnswered(result, entry: at, before: before)
 94	                    }
 95	                })
 96	        }
 97	    }
 98	
 99	    private func toolAnswered(_ result: String, entry: Int, before: Set<UInt32>) {
100	        let reply = (try? JSONSerialization.jsonObject(with: Data(result.utf8))) as? [String: Any]
101	        let content = reply?["content"] as? [[String: Any]] ?? []
102	        let text = content.compactMap { $0["text"] as? String }.joined(separator: "\n")
103	        showMeRun?.results.append(text)
104	        if (reply?["isError"] as? Bool) ?? true {
105	            finishShowMe(error: text.isEmpty ? "The call failed." : text)
106	            return
107	        }
108	        if let document { noteCreated(since: before, in: document) }
109	        runShowMeEntry(entry + 1)
110	    }
111	
112	    /// `$created` becomes what this call added, when it added any.
113	    private func noteCreated(since before: Set<UInt32>, in document: ProjectDocument) {
114	        let snapshot = document.editedProject.snapshot
115	        let added = snapshot.clips.map(\.id).filter { !before.contains($0) }
116	        if !added.isEmpty { created = TutorialVariables.timeOrdered(added, in: snapshot) }
117	    }
118	
119	    private func noteCreated(since before: Set<UInt32>) {
120	        if let document { noteCreated(since: before, in: document) }
121	    }
122	
123	    private func finishShowMe(error: String?) {
124	        guard let run = showMeRun else { return }
125	        lastShowMe = TutorialShowMeOutcome(
126	            step: run.step, ok: error == nil, error: error, results: run.results, paths: run.paths)
127	        showMeRun = nil
128	        showMeRunning = false
129	        heldEvaluation = false
130	        trigger()
131	    }
132	
133	    /// The menu form: nil once the item ran, else why not.
134	    private func performMenu(_ path: [String]) -> String? {
135	        let shown = path.joined(separator: " ▸ ")
136	        let window = editor?.view.window
137	        guard case .item(let item) = UIMenu.lookup(path, window: window) else {
138	            return "The menu bar has no \(shown)."
139	        }
140	        guard let target = UIMenu.target(for: item, window: window),
141	              UIMenu.isEnabled(item, target: target)
142	        else { return "\(shown) is not available now." }
143	        guard UIMenu.perform(item, target: target, window: window) else {
144	            return "\(shown) was not handled."
145	        }
146	        return nil
147	    }
148	
149	    /// An `export` path, tilde-expanded, made free by the Finder's rule.
150	    static func freeURL(for path: String) -> URL {
151	        let url = URL(fileURLWithPath: (path as NSString).expandingTildeInPath)
152	        return RecordingFiles.uniqueURL(
153	            in: url.deletingLastPathComponent(), stem: url.deletingPathExtension().lastPathComponent,
154	            ext: url.pathExtension)
155	    }
156	}
